		Fd:     int32(file.Fd()),
	})
	if err != nil {
		_ = unix.Close(epoll)
		_ = r.cancelSignalReader.Close()
		_ = r.cancelSignalWriter.Close()
		return nil, fmt.Errorf("add reader to epoll interest list: %w", err)
